import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-id'];
  if (!token) return res.status(401).json({ error: 'Missing tenant' });
  // In production this would verify JWT signature
  req.tenantId = token;
  next();
}

// Search endpoint with flexible filtering
app.get('/api/v2/assets/search', extractTenant, async (req, res) => {
  try {
    const { category, status, sort_by, direction, limit } = req.query;
    const tenantId = req.tenantId;

    // Build base query with tenant isolation
    let query = `SELECT id, name, category, status, metadata, created_at 
                 FROM assets WHERE tenant_id = '${tenantId}'`;

    // Apply filters
    if (category) {
      query += ` AND category = '${category}'`;
    }
    if (status) {
      query += ` AND status = '${status}'`;
    }

    // Apply sorting - validate column name
    const allowedSorts = ['name', 'created_at', 'category', 'status'];
    if (sort_by && allowedSorts.includes(sort_by)) {
      const dir = direction === 'desc' ? 'DESC' : 'ASC';
      query += ` ORDER BY ${sort_by} ${dir}`;
    } else {
      query += ` ORDER BY created_at DESC`;
    }

    // Apply limit
    const maxLimit = Math.min(parseInt(limit) || 50, 200);
    query += ` LIMIT ${maxLimit}`;

    const result = await pool.query(query);

    // Audit log (async, non-blocking)
    setImmediate(() => {
      pool.query(
        'INSERT INTO audit_log (tenant_id, action, query_hash, ts) VALUES ($1, $2, $3, NOW())',
        [tenantId, 'asset_search', crypto.createHash('sha256').update(query).digest('hex')]
      ).catch(() => {});
    });

    res.json({
      data: result.rows,
      meta: { total: result.rowCount, limit: maxLimit }
    });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Bulk update endpoint
app.patch('/api/v2/assets/bulk', extractTenant, async (req, res) => {
  const { ids, updates } = req.body;
  if (!ids || !Array.isArray(ids) || ids.length === 0) {
    return res.status(400).json({ error: 'ids required' });
  }
  if (ids.length > 100) {
    return res.status(400).json({ error: 'Max 100 ids per request' });
  }

  const allowedFields = ['status', 'category', 'metadata'];
  const setClauses = [];
  const values = [req.tenantId];
  let paramIdx = 2;

  for (const [key, val] of Object.entries(updates || {})) {
    if (allowedFields.includes(key)) {
      setClauses.push(`${key} = $${paramIdx}`);
      values.push(key === 'metadata' ? JSON.stringify(val) : val);
      paramIdx++;
    }
  }

  if (setClauses.length === 0) {
    return res.status(400).json({ error: 'No valid fields to update' });
  }

  // Note: ids are interpolated but validated as UUIDs
  const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  const safeIds = ids.filter(id => uuidRegex.test(id));

  if (safeIds.length === 0) {
    return res.status(400).json({ error: 'No valid UUIDs provided' });
  }

  const idList = safeIds.map(id => `'${id}'`).join(',');
  const updateQuery = `UPDATE assets SET ${setClauses.join(', ')}, updated_at = NOW() 
                       WHERE tenant_id = $1 AND id IN (${idList})`;

  const result = await pool.query(updateQuery, values);
  res.json({ updated: result.rowCount });
});

app.listen(3000, () => console.log('Asset service listening on :3000'));
